mapper.sql:
WHERE P.DELETED_AT IS NULL AND P.STATUS = 'ACTIVE'

    AND (P.NAME LIKE CONCAT('%', #{q.keyword}, '%')
         OR P.BRAND LIKE CONCAT('%', #{q.keyword}, '%'))


    AND (P.CATEGORY_ID = #{q.categoryId}
         OR P.CATEGORY_ID IN (
            SELECT C2.CATEGORY_ID FROM PRODUCT_CATEGORIES C2
            WHERE C2.PARENT_ID = #{q.categoryId}
               OR C2.CATEGORY_ID IN (
                   SELECT C3.CATEGORY_ID FROM PRODUCT_CATEGORIES C3
                   WHERE C3.PARENT_ID IN (
                       SELECT CATEGORY_ID FROM PRODUCT_CATEGORIES WHERE PARENT_ID = #{q.categoryId}
                   )
               )
         )
    )

AND P.SALE_PRICE >= #{q.priceMin}
AND P.SALE_PRICE <= #{q.priceMax}
AND (P.WIDTH_CM IS NULL OR P.WIDTH_CM <= #{q.widthMax})
AND (P.DEPTH_CM IS NULL OR P.DEPTH_CM <= #{q.depthMax})
AND (P.HEIGHT_CM IS NULL OR P.HEIGHT_CM <= #{q.heightMax})

mapper.select:
SELECT P.PRODUCT_ID, P.NAME, P.BRAND, P.PRICE, P.SALE_PRICE, CASE WHEN P.PRICE = 0 THEN 0 ELSE CAST(ROUND((P.PRICE - P.SALE_PRICE) * 100.0 / P.PRICE) AS SIGNED) END AS DISCOUNT_RATE, (SELECT PI.S3_URL FROM PRODUCT_IMAGES PI WHERE PI.PRODUCT_ID = P.PRODUCT_ID ORDER BY PI.IS_COVER DESC, PI.SORT_ORDER ASC LIMIT 1) AS COVER_IMAGE_URL, P.CATEGORY_ID, C.NAME AS CATEGORY_NAME, P.WIDTH_CM, P.DEPTH_CM, P.HEIGHT_CM, COALESCE(RS.AVERAGE_RATING, 0) AS AVERAGE_RATING, COALESCE(RS.REVIEW_COUNT, 0) AS REVIEW_COUNT FROM PRODUCTS P JOIN PRODUCT_CATEGORIES C ON C.CATEGORY_ID = P.CATEGORY_ID LEFT JOIN ( SELECT PRODUCT_ID, AVG(RATING) AS AVERAGE_RATING, CAST(COUNT(*) AS SIGNED) AS REVIEW_COUNT FROM PRODUCT_REVIEWS GROUP BY PRODUCT_ID ) RS ON RS.PRODUCT_ID = P.PRODUCT_ID
ORDER BY P.SALE_PRICE ASC ORDER BY P.SALE_PRICE DESC ORDER BY DISCOUNT_RATE DESC ORDER BY P.CREATED_AT DESC
LIMIT #{limit} OFFSET #{offset}

SELECT S3_URL FROM PRODUCT_IMAGES
WHERE PRODUCT_ID = #{productId}
ORDER BY IS_COVER DESC, SORT_ORDER ASC

SELECT STOCK FROM PRODUCT_OPTIONS
WHERE PRODUCT_OPTION_ID = #{productOptionId}
FOR UPDATE
